/* From Uiverse.io by Type-Delta  - Tags: animation, minimalist, theme-switch, light&dark, toggle switch */
/* a clone from joshwcomeau.com 
 * but this version runs on pure CSS
 */

.__UIV_SCOPE__ .themeToggle {
  color: #bbb;
  width: 3em;
}

.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn {
  position: relative;
  cursor: pointer;
}

.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn .themeToggleInput {
  opacity: 0;
  width: 100%;
  aspect-ratio: 1;
}

.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn svg {
  position: absolute;
  left: 0;
  width: 100%;
  height: 100%;
  transition: transform 0.4s ease;
  transform: rotate(40deg);
}

.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn svg .sunMoon {
  transform-origin: center center;
  transition: inherit;
  transform: scale(1);
}

.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn svg .sunRay {
  transform-origin: center center;
  transform: scale(0);
}

.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn svg mask > circle {
  transition: transform 0.64s cubic-bezier(0.41, 0.64, 0.32, 1.575);
  transform: translate(0px, 0px);
}

.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn svg .sunRay2 {
  animation-delay: 0.05s !important;
}
.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn svg .sunRay3 {
  animation-delay: 0.1s !important;
}
.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn svg .sunRay4 {
  animation-delay: 0.17s !important;
}
.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn svg .sunRay5 {
  animation-delay: 0.25s !important;
}
.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn svg .sunRay5 {
  animation-delay: 0.29s !important;
}

.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn .themeToggleInput:checked + svg {
  transform: rotate(90deg);
}
.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn .themeToggleInput:checked + svg mask > circle {
  transform: translate(16px, -3px);
}
.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn .themeToggleInput:checked + svg .sunMoon {
  transform: scale(0.55);
}
.__UIV_SCOPE__ .st-sunMoonThemeToggleBtn .themeToggleInput:checked + svg .sunRay {
  animation: showRay1832 0.4s ease 0s 1 forwards;
}

@keyframes showRay1832 {
  0% {
    transform: scale(0);
  }
  100% {
    transform: scale(1);
  }
}
